CROSS JOIN (VALUES
  ('A4_SH01', $pp${"positivePrompt": "{STYLE}, {PALETTE_A4}, extreme wide shot from low street angle of Palace of Republic in Minsk at night March 2021, brutalist marble facade lit from below by floodlights two massive turquoise BIO+ vertical banners hanging the full height of front pillars, stream of warm yellow taxi lights moving along avenue in foreground, cold winter air with breath-mist on a few pedestrians in silhouette near entrance, overcast night sky with light pollution glow, hard ink outline on columns banner edges taxi headlights cell-shaded color blocks cold marble grey hot turquoise banners warm taxi yellow streaks, EWS low angle locked off 16:9 iconic", "negativeRef": "{NEG}", "narrationRu": "Минск, март две тысячи двадцать первого, Дворец Республики, годовое собрание Брильянтового ранга"}$pp$, 'EWS', 'low', 'static', 'promise_of_premise', 'iconic', NULL, TRUE, TRUE, 'march_night_2021', 'A4_minsk_neon'),
